"""Citations are generated by code, never written by a model: a model selects
sentence ids, code slices the verbatim text and offsets from the TextStore."""

from __future__ import annotations

from verifier.output.schemas import Citation
from verifier.rag.source import TextStore


def make_citation(store: TextStore, sentence_id: str) -> Citation:
    sentence = store.sentence_by_id(sentence_id)
    return Citation(
        index=store.passage_index_of(sentence.span.doc),
        quote=store.slice(sentence.span),
        start_char=sentence.span.start,
        end_char=sentence.span.end,
    )


def citations_for_unit(store: TextStore, evidence_sentence_ids: list[str]) -> list[Citation]:
    seen: set[tuple[int, int]] = set()
    citations: list[Citation] = []
    for sentence_id in evidence_sentence_ids:
        c = make_citation(store, sentence_id)
        key = (c.index, c.start_char or -1)
        if key not in seen:
            seen.add(key)
            citations.append(c)
    citations.sort(key=lambda c: (c.index, c.start_char or 0))
    return citations
